import cn from 'classnames';
import { CarouselProps, ICarouselDefaultSlide, ICarouselTeaserSlide } from './carousel.types';

import './carousel.scss';
import Teaser from '../teaser/teaser';
import Image from '../image/image';

export function Carousel({
  id,
  className,
  classNameSlide,
  ':itemsOrder': itemsOrder,
  ':items': items,
  typeCarousel,
  autopauseDisabled = false,
  autoplay = false,
  controlsPrepended,
  delay = 5000,
  useExpand = false,
}: CarouselProps<ICarouselDefaultSlide | ICarouselTeaserSlide>) {
  const cnModifications = cn({
    'ds-brand-expand': useExpand,
  });
  const typeClassCarousel = cn({
    'carousel--hero': typeCarousel === 'hero',
    'carousel--hero-teaser': typeCarousel === 'hero-teaser',
  });

  return (
    <div className={cn('carousel panelcontainer', typeClassCarousel, cnModifications, className)}>
      <div
        id={id}
        className="cmp-carousel"
        role="group"
        aria-live="polite"
        aria-roledescription="carousel"
        data-cmp-delay={delay}
        data-cmp-data-layer=""
        {...(autoplay && { 'data-cmp-autoplay': '' })}
        data-placeholder-text="false"
      >
        <div className="cmp-carousel__content" aria-atomic="false" aria-live="polite">
          {itemsOrder.length &&
            itemsOrder.map((itemOrder, index) => (
              <div
                key={items[itemOrder].id}
                id={`${id}-item-${items[itemOrder].id?.split('-')[1]}-tabpanel`}
                className={cn('cmp-carousel__item', { 'cmp-carousel__item--active': index === 0 })}
                role="tabpanel"
                aria-labelledby={`${id}-item-${items[itemOrder].id?.split('-')[1]}-tab`}
                aria-roledescription="slide"
                aria-label={`Slide ${index + 1} of ${itemsOrder.length}`}
                data-cmp-data-layer=""
                data-cmp-hook-carousel="item"
                {...(index !== 0 && { 'aria-hidden': 'true' })}
              >
                {typeCarousel === 'image' || typeCarousel === 'hero' ? (
                  <Image key={index} {...(items[itemOrder] as ICarouselDefaultSlide)} />
                ) : null}
                {typeCarousel === 'teaser' || typeCarousel === 'hero-teaser' ? (
                  <Teaser
                    key={index}
                    {...(items[itemOrder] as ICarouselTeaserSlide)}
                    className={cn(items[itemOrder].className, classNameSlide)}
                  />
                ) : null}
              </div>
            ))}
          {controlsPrepended ? (
            <div className="cmp-carousel__actions">
              <button
                className="cmp-carousel__action cmp-carousel__action--previous"
                type="button"
                aria-label="Previous"
                data-cmp-hook-carousel="previous"
              >
                <span className="cmp-carousel__action-icon"></span>
                <span className="cmp-carousel__action-text">Previous</span>
              </button>
              <button
                className="cmp-carousel__action cmp-carousel__action--next"
                type="button"
                aria-label="Next"
                data-cmp-hook-carousel="next"
              >
                <span className="cmp-carousel__action-icon"></span>
                <span className="cmp-carousel__action-text">Next</span>
              </button>
              <button
                className={cn('cmp-carousel__action cmp-carousel__action--pause', {
                  'cmp-carousel__action--disabled': !autopauseDisabled,
                })}
                type="button"
                aria-label="Pause"
                data-cmp-hook-carousel="pause"
                {...(!autopauseDisabled && { disabled: true })}
              >
                <span className="cmp-carousel__action-icon"></span>
                <span className="cmp-carousel__action-text">Pause</span>
              </button>
              <button
                className={cn('cmp-carousel__action cmp-carousel__action--play', {
                  'cmp-carousel__action--disabled': autopauseDisabled,
                })}
                type="button"
                aria-label="Play"
                data-cmp-hook-carousel="play"
                {...(autopauseDisabled && { disabled: true })}
              >
                <span className="cmp-carousel__action-icon"></span>
                <span className="cmp-carousel__action-text">Play</span>
              </button>
            </div>
          ) : null}
          <ol
            className="cmp-carousel__indicators"
            role="tablist"
            aria-label="Choose a slide to display"
            data-cmp-hook-carousel="indicators"
          >
            {itemsOrder.length &&
              itemsOrder.map((itemOrder, index) => {
                const itemId = items[itemOrder].id?.split('-')[1];
                const title = items[itemOrder].title;
                return (
                  <li
                    key={index}
                    id={`${id}-item-${itemId}-tab`}
                    className={cn('cmp-carousel__indicator', { 'cmp-carousel__indicator--active': index === 0 })}
                    role="tab"
                    aria-controls={`${id}-item-${itemId}-tabpanel`}
                    aria-label="Slide 1"
                    data-cmp-hook-carousel="indicator"
                    aria-selected="true"
                    tabIndex={index === 0 ? 0 : -1}
                  >
                    {title}
                  </li>
                );
              })}
          </ol>
        </div>
      </div>
    </div>
  );
}

export default Carousel;
